{
  render: () => ({
    template: `
      <div style="padding: 24px;">
        <h2 style="margin-top: 0;">Brand Colors</h2>
        <p>Core colors that define the Dirawong brand identity.</p>

        <div
          style="
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 24px;
            margin-top: 24px;
          "
        >
          <!-- Primary Color -->
          <div>
            <div
              style="
                background: var(--dw-color-primary);
                height: 120px;
                border-radius: 12px;
                box-shadow: 0 2px 8px rgba(0,0,0,0.1);
              "
            ></div>

            <div style="margin-top: 12px;">
              <strong>Primary</strong>

              <div
                style="
                  font-size: 12px;
                  color: #64748b;
                  margin-top: 4px;
                "
              >
                <code>--dw-color-primary</code>
              </div>
            </div>
          </div>

          <!-- Accent Color -->
          <div>
            <div
              style="
                background: var(--dw-color-accent);
                height: 120px;
                border-radius: 12px;
                box-shadow: 0 2px 8px rgba(0,0,0,0.1);
              "
            ></div>

            <div style="margin-top: 12px;">
              <strong>Accent</strong>

              <div
                style="
                  font-size: 12px;
                  color: #64748b;
                  margin-top: 4px;
                "
              >
                <code>--dw-color-accent</code>
              </div>
            </div>
          </div>
        </div>
      </div>
    `,
  }),
  parameters: {
    docs: {
      description: {
        story:
          'Primary is used for main actions and core branding. Accent is used for emphasis, highlights, and secondary calls-to-action.',
      },
    },
  },
}

{
  render: (args) => ({
    moduleMetadata: {
      imports: [MatButtonModule],
    },
    props: args,
    template: `
      <div style="padding: 24px; display: flex; gap: 16px; flex-wrap: wrap;">
        ${args['variant'] === 'text' 
          ? `<button matButton [disabled]="disabled">{{ text }}</button>`
          : `<button matButton="${args['variant']}" [disabled]="disabled">{{ text }}</button>`
        }
        ${args['variant'] === 'text' 
          ? `<button matButton class="accent-button" [disabled]="disabled">{{ text }}</button>`
          : `<button matButton="${args['variant']}" class="accent-button" [disabled]="disabled">{{ text }}</button>`
        }
      </div>
    `,
  }),
}

{
  theme: {
    name: 'Theme',
    description: 'Global theme for components',
    defaultValue: 'hoot',
    toolbar: {
      icon: 'paintbrush',
      items: [
        { value: 'hoot', title: 'Hoot' },
        { value: 'kasisto', title: 'Kasisto' },
      ],
      showName: true,
    },
  },
}

{
  title: 'Components/Button',
  tags: ['autodocs'],
  parameters: {
    docs: {
      description: {
        component: `
Material buttons customized with Dirawong design tokens.

**Available Variants:**
- **Filled**: Solid background button (default)
- **Tonal**: Subtle filled button
- **Outlined**: Button with border
- **Text**: Plain text button

**Token Integration:**
- Border radius: \`--mat-button-*-container-shape: var(--dw-radius-md)\`
- Padding: \`var(--dw-space-3) var(--dw-space-4)\`
- Colors: \`--mat-sys-primary\`, \`--mat-sys-tertiary\`
        `,
      },
    },
  },
  argTypes: {
    variant: {
      control: 'select',
      options: ['filled', 'tonal', 'outlined', 'text'],
      description: 'Button style variant',
    },
    text: {
      control: 'text',
      description: 'Button label text',
    },
    disabled: {
      control: 'boolean',
      description: 'Disable the button',
    },
  },
  args: {
    variant: 'filled',
    text: 'Button',
    disabled: false,
  },
}

{
  title: 'Foundation/Colors',
  tags: ['autodocs'],
  parameters: {
    docs: {
      description: {
        component: `
Color tokens are the foundation of the Dirawong Design System.

**Token Architecture:**
- **Primitive tokens**: Raw color values (e.g., \`--dw-primitive-blue-900\`)
- **Semantic tokens**: Purpose-based colors (e.g., \`--dw-color-primary\`)

This layered approach allows rebranding by swapping primitives while keeping
semantic usage stable across the application.
        `,
      },
    },
  },
}

{
  parameters: {
    controls: {
      matchers: {
        color: /(background|color)$/i,
        date: /Date$/i,
      },
    },
  },
  decorators: [
    (storyFn, context) => {
      const theme = context.globals['theme'] || 'hoot';
      document.body.setAttribute('data-theme', theme);
      return storyFn();
    },
  ],
}

